import{_ as i,a0 as l,w as d,s as g,ao as r,I as a,x as e,a1 as n,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"修复 Ubuntu 中的 “Key is stored in legacy trusted.gpg keyring” 问题 | LCTT x X-CMD","titleTemplate":false,"description":"修复 Ubuntu 中的 “Key is stored in legacy trusted.gpg keyring” 问题 | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"修复 Ubuntu 中的 “Key is stored in legacy trusted.gpg keyring” 问题 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"修复 Ubuntu 中的 “Key is stored in legacy trusted.gpg keyring” 问题 | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20221118.0 ⭐️⭐️ Fixing “Key is stored in legacy trusted.gpg keyring” Issue in Ubuntu","title":"修复 Ubuntu 中的 “Key is stored in legacy trusted.gpg keyring” 问题","tag":"202302","desc":""},"relativePath":"202302/20221118.0 ⭐️⭐️ Fixing “Key is stored in legacy trusted.gpg keyring” Issue in Ubuntu.md","filePath":"[post].md"}'),o={name:"202302/20221118.0 ⭐️⭐️ Fixing “Key is stored in legacy trusted.gpg keyring” Issue in Ubuntu.md"};function u(c,s,k,h,y,b){const t=l("Link");return d(),g("div",null,[s[18]||(s[18]=r(`<h1 id="修复-ubuntu-中的-key-is-stored-in-legacy-trusted-gpg-keyring-问题" tabindex="-1">修复 Ubuntu 中的 “Key is stored in legacy trusted.gpg keyring” 问题 <a class="header-anchor" href="#修复-ubuntu-中的-key-is-stored-in-legacy-trusted-gpg-keyring-问题" aria-label="Permalink to “修复 Ubuntu 中的 “Key is stored in legacy trusted.gpg keyring” 问题”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202302/22/143209ysmxzrasycrxz7wa.jpg" alt=""></p><p>如果你在 Ubuntu 22.04 及以后的版本中使用 PPA 或添加外部仓库，你有可能会看到这样的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>W: https://packagecloud.io/slacktechnologies/slack/debian/dists/jessie/InRelease: Key is stored in legacy trusted.gpg keyring (/etc/apt/trusted.gpg), see the DEPRECATION section in apt-key(8) for details.</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/ubuntu-key-is-stored-legacy.png" alt="ubuntu key is stored legacy"></p><p>首先，这不是一个错误，而是一个警告信息。警告并不会导致程序停止工作。即使你在更新过程中看到这个警告信息，你也可以继续升级你的系统。</p><p>如果你不想看到这个警告信息，你可以采取一些手动步骤来摆脱它。</p><p>有两种方法；正确的方法和快速而不优雅的方法。阅读这两种方法，看看你对哪一种感到满意。</p><h3 id="方法-1-导入密钥-正确但复杂的方法" tabindex="-1">方法 1：导入密钥（正确但复杂的方法） <a class="header-anchor" href="#方法-1-导入密钥-正确但复杂的方法" aria-label="Permalink to “方法 1：导入密钥（正确但复杂的方法）”">​</a></h3><p>首先，列出所有添加到你系统中的 GPG 密钥。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-key list</span></span></code></pre></div><p>这将显示一个存储在你系统中的巨大的密钥列表。你在这里要做的是寻找与警告信息相关的密钥。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>abhishek@itsfoss:~$ sudo apt-key list</span></span>
<span class="line"><span>[sudo] password for abhishek: </span></span>
<span class="line"><span>Warning: apt-key is deprecated. Manage keyring files in trusted.gpg.d instead (see apt-key(8)).</span></span>
<span class="line"><span>/etc/apt/trusted.gpg</span></span>
<span class="line"><span>--------------------</span></span>
<span class="line"><span>pub   rsa4096 2014-01-13 [SCEA] [expired: 2019-01-12]</span></span>
<span class="line"><span>      418A 7F2F B0E1 E6E7 EABF  6FE8 C2E7 3424 D590 97AB</span></span>
<span class="line"><span>uid           [ expired] packagecloud ops (production key) &lt;abhishek@itsfoss&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>pub   rsa4096 2016-02-18 [SCEA]</span></span>
<span class="line"><span>      DB08 5A08 CA13 B8AC B917  E0F6 D938 EC0D 0386 51BD</span></span>
<span class="line"><span>uid           [ unknown] https://packagecloud.io/slacktechnologies/slack (https://packagecloud.io/docs#gpg_signing) &lt;abhishek@itsfoss&gt;</span></span>
<span class="line"><span>sub   rsa4096 2016-02-18 [SEA]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/etc/apt/trusted.gpg.d/audio-recorder-ubuntu-ppa.gpg</span></span>
<span class="line"><span>----------------------------------------------------</span></span>
<span class="line"><span>pub   rsa4096 2015-08-30 [SC]</span></span>
<span class="line"><span>      42EF 41ED 9813 B713 D4F1  F06D 5CF1 2638 ACF9 669F</span></span>
<span class="line"><span>uid           [ unknown] Launchpad PPA for Team audio-recorder</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/etc/apt/trusted.gpg.d/danielrichter2007-ubuntu-grub-customizer.gpg</span></span>
<span class="line"><span>-------------------------------------------------------------------</span></span>
<span class="line"><span>pub   rsa1024 2010-10-08 [SC]</span></span>
<span class="line"><span>      59DA D276 B942 642B 1BBD  0EAC A8AA 1FAA 3F05 5C03</span></span></code></pre></div><p>你要怎么做？仔细阅读该信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>W: https://packagecloud.io/slacktechnologies/slack/debian/dists/jessie/InRelease: Key is stored in legacy</span></span></code></pre></div><p>在我的例子中，仓库有 <code>packagecloud</code>、<code>slacktechnologies</code> 等关键词。它显示在 <code>apt-key</code> 列表输出的顶部。在你的情况下，你可能需要滚动一下。</p><p>在这种罕见的情况下，由 Slack 添加的外部仓库，有两个 GPG 密钥。其中一个已经过期，我会忽略它。你可能不会有这样的情况。</p><p>你应该看到 <code>pub</code> 后一行的最后 8 个字符（不包括空格）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/etc/apt/trusted.gpg</span></span>
<span class="line"><span>--------------------</span></span>
<span class="line"><span>pub   rsa4096 2014-01-13 [SCEA] [expired: 2019-01-12]</span></span>
<span class="line"><span>      418A 7F2F B0E1 E6E7 EABF  6FE8 C2E7 3424 D590 97AB</span></span>
<span class="line"><span>uid           [ expired] packagecloud ops (production key) &lt;abhishek@itsfoss&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>pub   rsa4096 2016-02-18 [SCEA]</span></span>
<span class="line"><span>      DB08 5A08 CA13 B8AC B917  E0F6 D938 EC0D 0386 51BD</span></span>
<span class="line"><span>uid           [ unknown] https://packagecloud.io/slacktechnologies/slack (https://packagecloud.io/docs#gpg_signing) &lt;abhishek@itsfoss&gt;</span></span></code></pre></div><p>因此，从 <code>DB08 5A08 CA13 B8AC B917 E0F6 D938 EC0D 0386 51BD</code> 这行中，我将提取最后8个字符 <code>0386 51BD</code>，去掉空格，然后用它来导入 <code>/etc/apt/trusted.gpg.d</code> 目录下专用文件中的 GPG 密钥：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-key export 038651BD | sudo gpg --dearmour -o /etc/apt/trusted.gpg.d/slack.gpg</span></span></code></pre></div><p>我在这里创建了一个新的文件 <code>slack.gpg</code>，以防你没有注意到它。我把它命名为 <code>slack.gpg</code> 是因为它与我之前安装的 Slack 应用有关。文件名并不重要，但它对识别有好处。</p><p>如果命令运行成功，你将不会看到任何信息。你可以通过检查新创建的 gpg 文件是否存在来验证。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/import-gpg-key-to-trusted-ubuntu.png" alt="import gpg key to trusted ubuntu"></p><p>再次运行更新，现在你应该不会再看到警告信息了。</p><h3 id="方法-2-复制到-trusted-gpd-d-目录中-快速而不优雅的方法" tabindex="-1">方法 2：复制到 trusted.gpd.d 目录中（快速而不优雅的方法） <a class="header-anchor" href="#方法-2-复制到-trusted-gpd-d-目录中-快速而不优雅的方法" aria-label="Permalink to “方法 2：复制到 trusted.gpd.d 目录中（快速而不优雅的方法）”">​</a></h3><p>如果你觉得手动做上面的事情不舒服，那么，你可以忽略这个警告信息。我的意思是，忽略它总是一种选择。</p><p>另一个选择是把 <code>/etc/apt/trusted.gpg</code> 文件复制到 <code>/etc/apt/trusted.gpg.d</code> 目录。毕竟，Ubuntu 只是抱怨说它需要 <code>/etc/apt/trusted.gpg.d</code> 目录下的 GPG 密钥。</p><p>你仍然要使用终端。打开它并使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo cp /etc/apt/trusted.gpg /etc/apt/trusted.gpg.d</span></span></code></pre></div><p>现在，如果你运行更新，你就不会再看到 “Key is stored in legacy trusted.gpg keyring” 的警告信息。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/quick-dirty-way-to-fix-apt-key-stored-legacy.png" alt="quick dirty way to fix apt key stored legacy"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3>`,33)),a("p",null,[s[1]||(s[1]=e("我曾经写过一篇关于 ",-1)),n(t,{href:"https://itsfoss.com/apt-key-deprecated/"},{default:p(()=>[...s[0]||(s[0]=[e("弃用 apt-key",-1)])]),_:1}),s[2]||(s[2]=e(" 的详细文章。显然，那篇文章让一些读者感到困惑，因此我写了这篇文章，给他们提供摆脱该信息的直接步骤。",-1))]),s[19]||(s[19]=a("p",null,[e("正如我之前所说，这是一个警告信息，目前可以忽略。解决这个问题的责任在于外部软件开发者和 Ubuntu 开发者。外部软件开发者应该确保他们的 GPG 密钥不再被添加到 "),a("code",null,"/etc/apt/trusted.gpg"),e(" 文件中。")],-1)),s[20]||(s[20]=a("p",null,"终端用户不应该为他们的懒惰而承担痛苦。",-1)),s[21]||(s[21]=a("p",null,"那么，你是用哪种方法来摆脱 “key is stored in legacy” 的警告信息的呢？第一个方法还是第二个方法？",-1)),s[22]||(s[22]=a("hr",null,null,-1)),a("p",null,[s[4]||(s[4]=e("via: ",-1)),n(t,{href:"https://itsfoss.com/key-is-stored-in-legacy-trusted-gpg/"},{default:p(()=>[...s[3]||(s[3]=[e("https://itsfoss.com/key-is-stored-in-legacy-trusted-gpg/",-1)])]),_:1})]),a("p",null,[s[9]||(s[9]=e("作者：",-1)),n(t,{href:"https://itsfoss.com/"},{default:p(()=>[...s[5]||(s[5]=[e("Abhishek Prakash",-1)])]),_:1}),s[10]||(s[10]=e(" 选题：",-1)),n(t,{href:"https://github.com/lkxed"},{default:p(()=>[...s[6]||(s[6]=[e("lkxed",-1)])]),_:1}),s[11]||(s[11]=e(" 译者：",-1)),n(t,{href:"https://github.com/geekpi"},{default:p(()=>[...s[7]||(s[7]=[e("geekpi",-1)])]),_:1}),s[12]||(s[12]=e(" 校对：",-1)),n(t,{href:"https://github.com/wxy"},{default:p(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[15]||(s[15]=e("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原创编译，",-1)),n(t,{href:"https://linux.cn/"},{default:p(()=>[...s[14]||(s[14]=[e("Linux中国",-1)])]),_:1}),s[17]||(s[17]=e(" 荣誉推出",-1))])])}const x=i(o,[["render",u]]);export{C as __pageData,x as default};
